      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a bucket-level Public Access Block",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "The bucket has no bucket-level controls preventing public ACLs or public bucket policies. Account-level settings may change, so the bucket should explicitly block all forms of public access."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket does not enforce KMS encryption",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly enforce SSE-KMS encryption, limiting control over key permissions, rotation, and auditability for potentially sensitive backend data."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is not enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "Without versioning, overwritten or deleted objects cannot be readily recovered. This is particularly risky for a bucket used to store backend data."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is not enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The bucket does not record server access logs, reducing the ability to investigate unauthorized access or anomalous requests."
    },
    {
      "check_id": "UNKNOWN",
      "title": "S3 bucket does not enforce encrypted transport",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "No bucket policy denies requests made without TLS, so clients can potentially send bucket requests over unencrypted transport."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Destructive bucket deletion is enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "Setting force_destroy to true allows Terraform to delete the bucket together with all stored object versions, increasing the impact of an accidental or malicious destroy operation."
    }
  ],
